WITH w AS (SELECT employee_id,YEARWEEK(meeting_date,1) wk,SUM(duration_hours) hrs FROM meetings GROUP BY employee_id,YEARWEEK(meeting_date,1) HAVING SUM(duration_hours)>20) SELECT e.employee_id,e.employee_name,e.department,COUNT(*) meeting_heavy_weeks FROM employees e JOIN w ON e.employee_id=w.employee_id GROUP BY e.employee_id,e.employee_name,e.department HAVING COUNT(*)>=2 ORDER BY meeting_heavy_weeks DESC,employee_name;